 "content": "from collections import Counter


def transform(grid):
    h, w = len(grid), len(grid[0])
    freq = Counter(v for row in grid for v in row)
    background = freq.most_common(1)[0][0]
    separator = freq.most_common(2)[1][0]

    # Horizontal lattice boundaries are rows dominated by the separator color.
    boundary_rows = [r for r, row in enumerate(grid)
                     if row.count(separator) > row.count(background)]
    if len(boundary_rows) < 2:
        return [[background]]

    # Colored marks occur at a fixed set of lattice intersections on each boundary.
    mark_cols = [c for c in range(w)
                 if any(grid[r][c] not in (background, separator) for r in boundary_rows)]
    out = []
    for r0, r1 in zip(boundary_rows, boundary_rows[1:]):
        row_out = []
        for c0, c1 in zip(mark_cols, mark_cols[1:]):
            vals = (grid[r0][c0], grid[r0][c1], grid[r1][c0], grid[r1][c1])
            row_out.append(vals[0] if vals[0] != background and len(set(vals)) == 1 else background)
        out.append(row_out)
    return out


if __name__ == '__main__':
    # Check the supplied demonstration and current test instance.
    demo = [[9 if c % 4 not in (1,) else 3 for c in range(26)] for _ in range(23)]
    # Vertical lattice lines are color 3; other cells are background 9.
    for r in range(23):
        for c in range(26):
            if r % 4 == 2 or c % 4 == 1:
                demo[r][c] = 3
    marks = {
        2: [1, 1, 7, 7], 6: [1, 1, 7, 7],
        10: [8, 8, 7, 7], 14: [8, 8, 2, 2],
        18: [0, 0, 2, 2], 22: [0, 0, 3, 3],
    }
    for r, colors in marks.items():
        for c, v in zip((5, 9, 13, 17), colors):
            demo[r][c] = v
    assert transform(demo) == [[1, 9, 7], [9, 9, 7], [8, 9, 9], [9, 9, 2], [0, 9, 9]]
    test = [[5] * 28 for _ in range(12)]
    for r in range(12):
